var n=`1043-soto-betawi`;var t=`world-1043`;var a=`ID`;var s=`southeast-asia`;var o=4;var r=115;var m={en:`Soto Betawi`,ua:`Сото бетаві`};var l={en:`Soto Betawi is a dish from Indonesia prepared with beef chuck, galangal, lemongrass, coconut milk. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Сото бетаві, страва кухні країни Індонезія, яку готують із таких продуктів: яловича лопатка, галангал, лемонграс, кокосове молоко. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,720,`g`],[`canola-oil`,45,`ml`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 60 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 60 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:60,i:[[`water`,1350,`ml`],[`galangal`,25,`g`],[`lemongrass`,2,`pcs`],[`star-anise`,2,`pcs`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 40 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 40 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:40,i:[[`coconut-milk`,490,`ml`],[`whole-cow-milk`,220,`ml`],[`potato`,240,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`tomato`,170,`g`],[`green-onion`,40,`g`]]}];var u={slug:n,id:t,country:`ID`,region:s,servings:4,minutes:115,title:m,text:l,steps:g};export{a as country,u as default,t as id,r as minutes,s as region,o as servings,n as slug,g as steps,l as text,m as title};